(1, 16, 16, '2026-27 Term 1', '["art_design", "words_stories", "nature_environment"]', '["drawing", "writing stories", "looking after the class plants"]', 'I like making things up and drawing them.', '2026-01-28', '2026-09-28 09:52:37', '2026-09-28 09:52:37'),
(2, 16, 16, '2026-27 Term 1', '["art_design", "computers_technology", "numbers_patterns", "words_stories"]', '["digital drawing", "the coding club", "writing stories"]', 'I started the coding club this year and I like making the drawings move.', '2026-09-08', '2026-09-28 09:52:37', '2026-09-28 09:52:37')
INSERT INTO "consent_records" ("id", "student_user_id", "granted_by_user_id", "purpose", "notice_text", "notice_version", "status", "verification_method", "granted_at", "withdrawn_at", "expires_at", "ip_address", "created_at", "updated_at") VALUES
(1, 16, 15, 'capability_growth', 'Teachers, and you, can record short notes about what your child is doing well and what they could use support with, across learning, social-emotional, creative, physical and life-skills areas. These notes are dated observations of moments — never a score, a grade, or a permanent label. They are visible to you, to your child''s teachers at this school, and to your child in an age-appropriate form. They are never public, never shown to other parents or students, and never used to place your child in an ability group.', '2026.09', 'granted', 'verified_parent_school_relationship', '2026-09-28 09:52:37', NULL, NULL, '127.0.0.1', '2026-09-28 09:52:37', '2026-09-28 09:52:37'),
(2, 16, 15, 'career_pathway', 'Your child can record what subjects and activities they enjoy, revisited each term as their interests change. The platform may show broad career and study areas to explore based on this. These are always options to look at, never an assigned track, and never a prediction about what your child will become.', '2026.09', 'granted', 'verified_parent_school_relationship', '2026-09-28 09:52:37', NULL, NULL, '127.0.0.1', '2026-09-28 09:52:37', '2026-09-28 09:52:37'),
(3, 16, 15, 'life_skills', 'The school can record which life-skills activities your child took part in — for example financial literacy, online safety, or civic education — and how they engaged. This records participation only. It is not a test and produces no score.', '2026.09', 'granted', 'verified_parent_school_relationship', '2026-09-28 09:52:37', NULL, NULL, '127.0.0.1', '2026-09-28 09:52:37', '2026-09-28 09:52:37'),
(4, 16, 15, 'physical_health', 'School health screenings and related records. Visible only to you, your child, and authorised school health staff.', '2026.09', 'granted', 'verified_parent_school_relationship', '2026-09-28 09:52:37', NULL, NULL, '127.0.0.1', '2026-09-28 09:52:37', '2026-09-28 09:52:37'),
(5, 16, 15, 'mental_wellbeing', 'Records kept by an authorised counsellor. Held under a stricter confidentiality tier than other records.', '2026.09', 'granted', 'verified_parent_school_relationship', '2026-09-28 09:52:37', NULL, NULL, '127.0.0.1', '2026-09-28 09:52:37', '2026-09-28 09:52:37')
