INSERT INTO "capability_observations" ("id", "student_user_id", "school_id", "observer_user_id", "observer_role", "domain", "strand", "observation_type", "observation", "evidence_context", "academic_term", "observed_on", "moderation_status", "moderated_by_user_id", "moderated_at", "created_at", "updated_at") VALUES
(1, 16, 1, 17, 'teacher', 'cognitive_scholastic', 'problem solving', 'strength', 'Kept working through a hard set of fraction problems after two wrong attempts, and asked for a hint rather than giving up.', 'During the Thursday maths practice session', '2026-27 Term 1', '2026-09-16', 'approved', NULL, NULL, '2026-09-28 09:52:37', '2026-09-28 09:52:37'),
(2, 16, 1, 17, 'teacher', 'socio_emotional', 'collaboration', 'strength', 'Noticed a classmate had been left out of a group and invited them in without being prompted.', 'Group science project, week 3', '2026-27 Term 1', '2026-09-18', 'approved', NULL, NULL, '2026-09-28 09:52:37', '2026-09-28 09:52:37'),
(3, 16, 1, 17, 'teacher', 'cognitive_scholastic', 'reading aloud', 'growth_area', 'Spoke very quietly when reading to the class and stopped a few times. Seemed more comfortable reading to a partner.', 'Class reading circle', '2026-27 Term 1', '2026-09-05', 'approved', NULL, NULL, '2026-09-28 09:52:37', '2026-09-28 09:52:37'),
(4, 16, 1, 15, 'parent', 'creative_co_scholastic', 'drawing and storytelling', 'strength', 'Spent most of the weekend illustrating a story she wrote herself, and explained the whole plot to us at dinner.', 'At home', '2026-27 Term 1', '2026-09-08', 'approved', NULL, NULL, '2026-09-28 09:52:37', '2026-09-28 09:52:37'),
(5, 16, 1, 15, 'parent', 'physical_development', 'stamina', 'growth_area', 'Found the longer walk on the school trip tiring and needed a few rests.', 'School trip to the fort', '2026-27 Term 1', '2026-09-16', 'approved', NULL, NULL, '2026-09-28 09:52:37', '2026-09-28 09:52:37'),
(6, 16, 1, 16, 'self', 'life_skills', 'organising my time', 'growth_area', 'I keep leaving my homework until the last evening and then it feels rushed.', NULL, '2026-27 Term 1', '2026-09-22', 'approved', NULL, NULL, '2026-09-28 09:52:37', '2026-09-28 09:52:37')
