INSERT INTO "growth_goals" ("id", "growth_plan_id", "domain", "goal_statement", "support_at_school", "support_at_home", "student_voice", "status", "review_note", "reviewed_at", "created_at", "updated_at") VALUES
(1, 1, 'cognitive_scholastic', 'Read aloud to the class with more confidence.', 'Start with reading to a partner, then a small group, before the full class. Two short turns a week.', 'Let her read a page aloud at home a few evenings a week — to a sibling or even the dog, anything that is low pressure.', NULL, 'in_progress', NULL, NULL, '2026-09-28 09:52:37', '2026-09-28 09:52:37'),
(2, 1, 'life_skills', 'Start homework earlier in the week so it is not rushed.', 'Write the week''s homework on the board every Monday and give ten minutes to plan it.', 'Agree a regular time on Tuesday and Wednesday evenings, and check in rather than remind repeatedly.', 'I want to try doing the hard one first instead of last.', 'in_progress', NULL, NULL, '2026-09-28 09:52:37', '2026-09-28 09:52:37')
